function storageKey(levelId) {
  return levelId === 4 ? "hsk4_progress" : `hsk${levelId}_progress`;
}
async function loadStorage(levelId) {
  try {
    const raw = localStorage.getItem(storageKey(levelId));
    if (raw) {
      const data = JSON.parse(raw);
      return {
        badList: data.badList || [],
        mastery: data.mastery || {},
      };
    }
  } catch {}
  return { badList: [], mastery: {} };
}
async function saveStorage(levelId, badList, mastery) {
  try {
    localStorage.setItem(storageKey(levelId), JSON.stringify({ badList, mastery }));
  } catch {}
}
function reviewStorageKey(levelId) {
  return `hsk${levelId}_review`;
}
function loadReview(levelId) {
  try {
    const raw = localStorage.getItem(reviewStorageKey(levelId));
    if (raw) {
      const data = JSON.parse(raw);
      return { index: data.index || 0, comments: data.comments || {} };
    }
  } catch {}
  return { index: 0, comments: {} };
}
function saveReview(levelId, index, comments) {
  try {
    localStorage.setItem(reviewStorageKey(levelId), JSON.stringify({ index, comments }));
  } catch {}
}
